 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Hi! Welcome to Nimbus Telecom. I'm Lucy. How can I help you today? 😊",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hey Lucy, my internet has been cutting out all morning. It's super annoying.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'm sorry to hear that. I can definitely look into this for you. Could you please provide your account number and date of birth for verification?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, account number is 89774974 and my dob is 04/08/1968. I'm James Wilson by the way.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thanks, James. I see there's some instability in the local exchange. I totally understand how frustrating it is when your connection drops during the day.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "Yeah, it's a nightmare. I'm trying to work from home. My phone number is 94760 01182 if that helps.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can assure you there won't be any more outages in your area.",
      "tags": [
        "prohibited_promise"
      ]
    },
    {
      "speaker": "customer",
      "text": "You say that, but it's happened three times this week. I'm honestly about to just switch to another provider.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I'm sorry, but there isn't much more I can do from my end right now. We are just waiting on the engineers.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "That's useless! I'm paying for a service I'm not getting. I'll just pay my current bill now to clear it so I can leave. My card is four one four seven one zero four nine seven four six five zero seven five two.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I've noted the payment. Is there anything else I can help you with today? We'll just have to wait for the network team to update the status. Goodbye!",
      "tags": [
        "closure"
      ]
    },
    {
      "speaker": "customer",
      "text": "No, nothing else. This is ridiculous. Bye.",
      "tags": []
    }
  ]
}
